     1	import type {
     2	  InputTextNode,
     3	  RoamBasicNode,
     4	  TextNode,
     5	} from "roamjs-components/types/native";
     6	import getSettingValueFromTree from "roamjs-components/util/getSettingValueFromTree";
     7	import toFlexRegex from "roamjs-components/util/toFlexRegex";
     8	import DEFAULT_RELATION_VALUES from "~/data/defaultDiscourseRelations";
     9	import {
    10	  isNewSettingsStoreEnabled,
    11	  getAllRelations,
    12	  type SettingsSnapshot,
    13	} from "~/components/settings/utils/accessors";
    14	import discourseConfigRef from "./discourseConfigRef";
    15	import { getStoredRelationsEnabled } from "~/utils/storedRelations";
    16	
    17	export type Triple = readonly [string, string, string];
    18	export type DiscourseRelation = {
    19	  triples: Triple[];
    20	  id: string;
    21	  label: string;
    22	  source: string;
    23	  destination: string;
    24	  complement: string;
    25	};
    26	
    27	const matchNodeText = (keyword: string) => {
    28	  return (node: RoamBasicNode | TextNode) =>
    29	    toFlexRegex(keyword).test(node.text);
    30	};
    31	
    32	export const getGrammarNode = () => {
    33	  return discourseConfigRef.tree.find(matchNodeText("grammar"));
    34	};
    35	
    36	export const getRelationsNode = (grammarNode = getGrammarNode()) => {
    37	  return grammarNode?.children.find(matchNodeText("relations"));
    38	};
    39	
    40	const getDiscourseRelations = (snapshot?: SettingsSnapshot) => {
    41	  const newStoreEnabled = snapshot
    42	    ? snapshot.featureFlags["Use new settings store"]
    43	    : isNewSettingsStoreEnabled();
    44	  if (newStoreEnabled) {
    45	    return getAllRelations(snapshot);
    46	  }
    47	
    48	  const grammarNode = getGrammarNode();
    49	  const relationsNode = getRelationsNode(grammarNode);
    50	  const relationNodes = relationsNode?.children || DEFAULT_RELATION_VALUES;
    51	  const storedRelationsEnabled = getStoredRelationsEnabled();
    52	  const discourseRelations = relationNodes.flatMap(
    53	    (r: InputTextNode, i: number) => {
    54	      const tree = (r?.children || []) as TextNode[];
    55	      const data = {
    56	        id: r.uid || `${r.text}-${i}`,
    57	        label: r.text,
    58	        source: getSettingValueFromTree({ tree, key: "Source" }),
    59	        destination: getSettingValueFromTree({ tree, key: "Destination" }),
    60	        complement: getSettingValueFromTree({ tree, key: "Complement" }),
    61	      };
    62	      const ifNode = tree.find(matchNodeText("if"))?.children || [];
    63	      if (ifNode.length === 0 && storedRelationsEnabled) {
    64	        return [{ ...data, triples: [] }];
    65	      }
    66	      return ifNode.map((node) => ({
    67	        ...data,
    68	        triples: node.children
    69	          .filter((t) => !/node positions/i.test(t.text))
    70	          .map((t) => {
    71	            const target = t.children[0]?.children?.[0]?.text || "";
    72	            return [t.text, t.children[0]?.text, target] as const;
    73	          }),
    74	      }));
    75	    },
    76	  );
    77	
    78	  return discourseRelations;
    79	};
    80	
    81	export default getDiscourseRelations;
