const DiscourseRelationConfigPanel = ({
  uid,
  parentUid,
}: {
  uid: string;
  parentUid: string;
  defaultValue: unknown;
  title: string;
}) => {
  const refreshRelations = useCallback(
    (): Relation[] =>
      Object.entries(getGlobalSettings().Relations).map(([id, relation]) => ({
        uid: id,
        text: relation.label,
        source: relation.source,
        destination: relation.destination,
      })),
    [],
  );
  const { nodes, configuredNodeTypes } = useMemo(() => {
    const discourseNodes = getDiscourseNodes();
    const nodes = Object.fromEntries(
      discourseNodes.map((n) => {
        const color = formatHexColor(n.canvasSettings.color);
        return [n.type, { label: n.text, format: n.format, color }];
      }),
    );
    // TypeError: Iterator value * is not an entry object
    nodes["*"] = { label: "Any", format: ".+", color: "#000" };
    const configuredNodeTypes = getRelationEndpointNodeTypes(discourseNodes);
    return { nodes, configuredNodeTypes };
  }, []);
  const previewUid = useSubTree({ parentUid, key: "preview" }).uid;
  const [translatorKeys, setTranslatorKeys] = useState(getConditionLabels);
  const [relations, setRelations] = useState(refreshRelations);
  const [sort, setSort] = useState<RelationSort | null>(null);
  const [editingRelation, setEditingRelation] = useState("");
  const [newRelation, setNewRelation] = useState("");
  const [deleteConfirmation, setDeleteConfirmation] = useState<string | null>(
    null,
  );
  const shouldHideCanvasRelation = getStoredRelationsEnabled();
  const visibleRelations = useMemo(() => {
    if (!shouldHideCanvasRelation) {
      return relations;
    }
    // Deprecated: hide "canvas" relations; this will be removed in the future
    // when the pattern -> stored relation migration is complete.
    return relations.filter((relation) => relation.text !== "canvas");
  }, [relations, shouldHideCanvasRelation]);
  const sortedRelations = useMemo(
    () =>
      sort
        ? sortRelations({
            relations: visibleRelations,
            sort,
            labelsByType: nodes,
          })
        : visibleRelations,
    [nodes, sort, visibleRelations],
  );
  // Acceptance lives in block props, not in the relations state, so the split
  // below is recomputed on every render and accepting bumps this reducer to
  // trigger one.
  const [, refreshImportMeta] = useReducer((version: number) => version + 1, 0);
  const localRelations: Relation[] = [];
  const importedRelations: ImportedRelation[] = [];
  for (const rel of sortedRelations) {
    const importMeta = readRelationSchemaImportMeta(rel.uid);
    if (importMeta) importedRelations.push({ ...rel, importMeta });
    else localRelations.push(rel);
  }
  const editingRelationInfo = useMemo(
    () =>
      editingRelation ? getFullTreeByParentUid(editingRelation) : undefined,
    [editingRelation],
  );
  const onNewRelation = () => {
    createBlock({
      parentUid: uid,
      order: relations.length,
      node: { text: "" },
    }).then((relationUid) => {
      setRelations([
        ...relations,
        {
          text: "",
          uid: relationUid,
          source: "?",
          destination: "?",
