export const setGlobalSetting = (keys: string[], value: json): void => {
  if (keys.length === 0) {
    internalError({
      error: "setGlobalSetting called with empty keys array",
      type: "DG Accessor",
    });
    return;
  }

  if (
    !validateSettingValue({
      schema: GlobalSettingsSchema,
      keys,
      value,
      context: "Global",
    })
  ) {
    return;
  }

  setBlockPropBasedSettings({
    keys: [STATIC_TOP_LEVEL_ENTRIES.global.key, ...keys],
    value,
  });
};

export const getAllRelations = (
  settings?: SettingsSnapshot,
): DiscourseRelation[] => {
  const globalSettings = settings
    ? settings.globalSettings
    : getGlobalSettings();

  const storedRelationsEnabled = getStoredRelationsEnabled();
  return Object.entries(globalSettings.Relations).flatMap(([id, relation]) => {
    const base = {
      id,
      label: relation.label,
      source: relation.source,
      destination: relation.destination,
      complement: relation.complement,
    };
    if (relation.ifConditions.length === 0 && storedRelationsEnabled)
      return [{ ...base, triples: [] }];
    return relation.ifConditions.map((c) => ({ ...base, triples: c.triples }));
  });
};

